diff --git a/features/support/world.js b/features/support/world.js
index 5f20359..dc0ccc2 100644
--- a/features/support/world.js
+++ b/features/support/world.js
@@ -84,6 +84,20 @@ class TodoWorld {
     }
   }

+  // True when `el` or any ancestor is hidden via CSS `display: none`. A
+  // `display:none` ancestor means the subtree is not rendered, even though
+  // `getComputedStyle(child).display` keeps the child's own resolved value.
+  isHiddenByCss(el) {
+    let node = el;
+    while (node && node.nodeType === 1) {
+      if (this.window.getComputedStyle(node).display === 'none') {
+        return true;
+      }
+      node = node.parentElement;
+    }
+    return false;
+  }
+
   // --- DOM interaction helpers ---

   get el() {
